#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>
int main() {
    const std::vector<int> values{3, 5, 7, 9};
    if (values.empty()) { std::cout << "no data\n"; return 0; }
    const int sum = std::accumulate(values.begin(), values.end(), 0);
    const auto [minimum, maximum] = std::minmax_element(values.begin(), values.end());
    std::cout << "count=" << values.size() << ", sum=" << sum << ", average="
              << static_cast<double>(sum) / values.size() << ", min=" << *minimum << ", max=" << *maximum << '\n';
}
